<?php ui_header('Tin nhắn','Trao đổi trực tiếp với recruiter hoặc ứng viên.'); ?>
<div class="messages-layout section" id="messaging" data-user="<?= e($user['id']) ?>"><aside class="conversation-list"><div class="conversation-heading"><h2>Tin nhắn</h2><a class="icon-button" href="/network" aria-label="Hội thoại mới"><?= ui_icon('edit',18) ?></a></div><div class="conversation-search"><input id="conversation-search" aria-label="Tìm hội thoại" placeholder="Tìm kiếm hội thoại..."></div><div class="conversation-items"><?php foreach($data as $conversation): $names=[];$online=false;foreach($conversation['participants'] as $participant)if($participant['userId']!==$user['id']){$names[]=$participant['user']['profile']['fullName']??'Thành viên';$online=$online||$participant['online'];}$name=implode(', ',$names); ?><button class="conversation" data-conversation="<?= e($conversation['id']) ?>" data-title="<?= e($name) ?>" data-online="<?= $online?'true':'false' ?>"><span class="mini-avatar"><?= e(mb_strtoupper(mb_substr($name,0,2))) ?></span><span><strong><?= e($name) ?></strong><small><?= e($conversation['messages'][0]['content']??'Chưa có tin nhắn') ?></small></span></button><?php endforeach; ?><?php if(!$data): ?><div class="empty-state"><p>Chưa có hội thoại.</p><a class="button secondary" href="/network">Tìm kết nối</a></div><?php endif; ?></div></aside>
<section class="message-thread"><header class="thread-header"><span class="mini-avatar" id="thread-avatar"><?= !empty($data)?e(mb_strtoupper(mb_substr($name,0,2))):'?' ?></span><div><h2 id="thread-title">Live Chat</h2><p id="thread-presence">Tin nhắn trực tiếp</p></div></header><p id="typing-status" aria-live="polite"></p><div class="thread-search"><input id="message-search" aria-label="Tìm trong cuộc trò chuyện" placeholder="Tìm tin nhắn cũ..."></div><button id="load-older-messages" class="ghost" type="button" hidden>Tải tin nhắn cũ hơn</button><div id="message-list" role="log" aria-live="polite"></div><form id="message-form"><label class="sr-only" for="message-input">Tin nhắn</label><input name="content" id="message-input" maxlength="5000" required autocomplete="off" placeholder="Nhập tin nhắn... (Enter để gửi)"><button aria-label="Gửi tin nhắn"><?= ui_icon('send',16) ?></button></form></section></div>
<dialog id="message-report-dialog" class="ui-dialog"><div class="dialog-heading"><h2>Báo cáo tin nhắn</h2><button type="button" class="icon-button" data-close-dialog aria-label="Đóng">×</button></div><div class="dialog-body"><p data-report-preview class="prose"></p><form><input type="hidden" name="targetId"><label>Lý do báo cáo<input name="reason" required maxlength="300" placeholder="Lý do báo cáo..."></label><div class="row"><button type="submit">Gửi báo cáo</button><button type="button" class="ghost" data-close-dialog>Hủy</button></div></form></div></dialog>